const pick = (words: readonly string[]) => {
  const [index] = crypto.getRandomValues(new Uint32Array(1));
  return words[(index ?? 0) % words.length] ?? words[0] ?? "site";
};

export const randomSlug = () => {
  const first = pick(ADJECTIVES);
  let second = pick(ADJECTIVES);
  while (second === first) second = pick(ADJECTIVES);
  return `${first}-${second}-${pick(NOUNS)}`;
};
